<template>
  <div class="assistant-workspace" :class="{ 'history-open': historyOpen, 'sources-open': sourcesOpen }">
    <aside class="history-panel">
      <div class="panel-heading">工作记录<button class="icon-btn mobile" aria-label="关闭会话栏" @click="historyOpen=false"><Close /></button></div>
      <button class="new-chat" :disabled="sending" @click="newChat"><Plus />新的对话</button>
      <div class="history-search"><Search /><input v-model="search" placeholder="搜索历史对话" aria-label="搜索历史对话"></div>
      <div class="history-list">
        <div v-for="c in filteredHistory" :key="c.id" :class="['history-item',{selected:current?.id===c.id}]">
          <button class="history-select" :disabled="sending" @click="openConversation(c.id)"><ChatLineRound /><span>{{ c.title }}</span></button>
          <el-dropdown trigger="click"><button class="icon-btn menu-btn" aria-label="对话操作"><MoreFilled /></button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="rename(c)">重命名</el-dropdown-item><el-dropdown-item @click="removeConversation(c)">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
        </div>
        <p v-if="!filteredHistory.length" class="muted-note">{{ search?'没有匹配的记录':'每次分析，都会保存于此。' }}</p>
      </div>
      <button class="library-link" @click="libraryOpen=true"><FolderOpened />我的资料<span>{{ files.filter(f=>f.kind==='DOCUMENT').length }}</span></button>
      <div class="readonly-note"><i />平台业务数据只读<p>查询、比较与解释，保留分析依据。</p></div>
    </aside>

    <main class="chat-panel" v-loading="loading">
      <header class="chat-header">
        <button class="icon-btn mobile" aria-label="打开历史会话" @click="historyOpen=true"><Menu /></button>
        <div class="leaf-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M7 25C4 13 12 6 26 5c0 14-5 23-17 21M8 26L23 10M13 20l-1-6M18 15l6 1" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" /></svg></div>
        <div><h1>Leafora 农业助手</h1><p>从田间记录，找到下一步的依据</p></div>
        <span :class="['service-state',{available:capabilities?.model_configured}]"><i />{{ capabilities?.model_configured?'智能分析已启用':'结构化查询模式' }}</span>
        <button class="icon-btn sources-toggle" aria-label="查看分析依据" @click="sourcesOpen=!sourcesOpen"><Document /></button>
      </header>
      <div class="context-bar">
        <el-select v-model="context.field_id" clearable placeholder="全部烟田" :disabled="busy" @change="fieldChanged" aria-label="选择烟田"><el-option v-for="f in fields" :key="f.field_id" :value="f.field_id" :label="f.name" /></el-select>
        <el-select v-model="context.inspection_id" clearable filterable placeholder="选择巡检" :disabled="busy" @change="persistContext" aria-label="选择巡检"><el-option v-for="e in availableInspections" :key="e.inspection_id" :value="e.inspection_id" :label="`${e.name} · ${day(e.started_at)}`" /></el-select>
        <button class="background-button" :disabled="busy" @click="backgroundOpen=true"><Setting /><span>{{ context.location || context.growth_stage || '作物与天气地点' }}</span></button>
      </div>

      <section ref="scrollArea" class="chat-scroll" @scroll="rememberScroll">
        <div v-if="!messages.length" class="welcome">
          <h2>读懂田间数据<br>找到下一步的依据</h2>
          <p>聊聊作物，查查天气，或从一次巡检开始。<br>需要依据的地方，我会帮你找到来源。</p>
          <div class="starters"><button v-for="s in starters" :key="s.title" :disabled="busy" @click="send(s.question)"><component :is="s.icon" /><b>{{ s.title }}</b><span>{{ s.description }}</span><ArrowUpRight /></button></div>
          <p v-if="capabilities && !capabilities.model_configured" class="setup-note">智能对话尚未启用，目前可查看已授权的平台查询结果。</p>
        </div>
        <div v-else class="message-list">
          <article v-for="m in messages" :key="m.id" :class="['message',m.role]">
            <div v-if="m.role==='assistant'" class="message-label"><span class="mini-leaf">L</span>Leafora<time>{{ clock(m.created_at) }}</time></div>
            <p v-if="m.role==='user'" class="user-question">{{ m.content }}</p>
            <AssistantAnswer v-else :text="m.content" :evidence="m.evidence" @cite="selectSource(m,$event)" />
            <div v-if="m.attachment_ids.length" class="message-files"><button v-for="id in m.attachment_ids" :key="id" @click="downloadFile(id)"><Paperclip />{{ files.find(f=>f.id===id)?.title || '已移除附件' }}</button></div>
            <div v-if="m.role==='assistant' && ['RUNNING','QUEUED'].includes(m.status)" class="progress"><i />{{ progress }}</div>
            <p v-if="m.role==='assistant' && ['FAILED','INTERRUPTED','CANCELLED'].includes(m.status)" class="run-note">{{ m.status==='CANCELLED'?'已停止生成，内容已保留。':'本次回答未完成，可以重新生成。' }}</p>
            <div v-if="m.role==='assistant' && m.evidence.length" class="inline-sources"><button v-for="e in m.evidence.slice(0,4)" :key="e.id" @click="selectSource(m,e.id)"><span>{{ e.id }}</span>{{ e.title }}</button><button v-if="m.evidence.length>4" @click="showSources(m,true)">+{{ m.evidence.length-4 }} 项依据</button></div>
            <div v-if="m.role==='assistant' && !['RUNNING','QUEUED'].includes(m.status)" class="answer-actions"><button @click="copy(m.content)"><CopyDocument />复制</button><button :disabled="busy" @click="regenerate(m)"><RefreshRight />重新生成</button><button @click="exportAnswer(m,'md')"><Download />报告</button><button v-if="m.evidence.length" @click="exportAnswer(m,'csv')">CSV</button></div>
          </article>
        </div>
      </section>

      <div class="composer-area">
        <button v-if="!atBottom && messages.length" class="jump-bottom" @click="scrollBottom(true)">最新回答 ↓</button>
        <div v-if="pending.length" class="pending-files"><span v-for="f in pending" :key="f.id"><Paperclip />{{ f.title }}<button aria-label="移除待发送附件" @click="pending=pending.filter(p=>p.id!==f.id)"><Close /></button></span></div>
        <div :class="['composer',{focused:inputFocused}]"><textarea ref="input" v-model="question" rows="3" maxlength="4000" :disabled="sending" placeholder="询问作物知识、天气，或你的巡检数据…" aria-label="向农业助手提问" @focus="inputFocused=true" @blur="inputFocused=false" @keydown="handleKey" />
          <div class="composer-tools"><div class="tools-left"><button class="icon-btn" :disabled="busy||uploading" aria-label="上传图片或文档" @click="fileInput?.click()"><Loading v-if="uploading" class="spin" /><Paperclip v-else /></button><button :class="['tool-toggle',{enabled:webEnabled}]" :disabled="busy" :title="capabilities?.search_configured?'按需联网查询':'联网资料服务尚未配置'" @click="webEnabled=!webEnabled"><Connection />联网</button><button :class="['tool-toggle',{enabled:imageEnabled}]" :disabled="busy" @click="imageEnabled=!imageEnabled"><Picture />图片分析</button></div><span class="input-count">{{ question.length }}/4000</span><button v-if="activeRun" class="stop-button" @click="stop"><VideoPause />停止</button><button v-else class="send-button" aria-label="发送问题" :disabled="sending||uploading||question.trim().length<2" @click="send(question)"><ArrowUp /></button></div>
        </div>
        <div v-if="error" class="error-note">{{ error }}<button v-if="retryRequest&&!busy" @click="retrySubmission">重试提交</button><button v-if="activeRun" @click="resume">恢复连接</button></div>
        <input ref="fileInput" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf,.docx,.txt,.md" multiple hidden @change="uploadFiles">
      </div>
    </main>

    <aside class="sources-panel">
      <div class="panel-heading">分析依据<button class="icon-btn close-sources" aria-label="关闭分析依据" @click="sourcesOpen=false"><Close /></button></div>
      <template v-if="sourceList.length"><div class="source-tabs"><button v-for="e in sourceList" :key="e.id" :class="{selected:selectedSource?.id===e.id}" @click="selectedSource=e">{{ e.id }}</button></div><AssistantEvidence :evidence="selectedSource" /></template>
      <div v-else class="sources-empty"><Document /><h3>回答有据可查</h3><p>查询巡检、天气或资料后，<br>在这里查看数据与来源。</p><details class="provider-settings"><summary>服务状态</summary><div class="provider-status"><span>智能对话<b>{{ capabilities?.model_configured?'已配置':'待配置' }}</b></span><span>实时天气<b>{{ capabilities?.weather_configured?'已配置':'待配置' }}</b></span><span>联网资料<b>{{ capabilities?.search_configured?'已配置':'待配置' }}</b></span></div></details></div>
    </aside>
    <button v-if="historyOpen||sourcesOpen" class="backdrop" aria-label="关闭侧栏" @click="historyOpen=false;sourcesOpen=false" />

    <el-drawer v-model="backgroundOpen" title="本次分析背景" size="min(420px, 100vw)"><div class="background-form"><p>这些信息只用于助手分析，不修改烟田边界或巡检快照。</p><label>作物<el-input v-model="context.crop" maxlength="40" /></label><label>品种（可选）<el-input v-model="variety" maxlength="60" /></label><label>生育期（可选）<el-input v-model="context.growth_stage" maxlength="60" placeholder="例如：移栽后、旺长期" /></label><label>真实天气地点<el-input v-model="context.location" maxlength="100" placeholder="例如：云南省曲靖市麒麟区" /></label><p class="location-note">模拟校准坐标不用于真实天气。重名地点会请你确认。</p><el-button type="primary" @click="saveBackground">保存分析背景</el-button></div></el-drawer>
    <el-drawer v-model="libraryOpen" title="我的资料" size="min(480px, 100vw)"><p class="library-intro">文档仅对你可见。支持文字型 PDF、DOCX、TXT 和 Markdown；图片可随问题发送。</p><button class="new-chat" :disabled="uploading||busy" @click="fileInput?.click()"><Plus />上传资料</button><div v-for="f in files" :key="f.id" class="library-file"><Document /><div><b>{{ f.title }}</b><span>{{ (f.byte_size/1024).toFixed(0) }} KB · {{ f.kind==='IMAGE'?'图片':`${f.chunk_count} 个资料片段` }}</span></div><button class="icon-btn" :disabled="busy" aria-label="添加到问题" @click="attach(f)"><Plus /></button><button class="icon-btn" aria-label="移除资料" @click="removeFile(f)"><Delete /></button></div><p v-if="!files.length" class="muted-note">还没有上传资料。</p></el-drawer>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowUp, TopRight as ArrowUpRight, ChatLineRound, Close, Connection, CopyDocument, DataAnalysis, Delete, Document, Download, FolderOpened, Loading, Menu, MoreFilled, Paperclip, Picture, Plus, RefreshRight, Search, Setting, Sunny, VideoPause } from '@element-plus/icons-vue'
import { assistantApi, watchRun, type Attachment, type AssistantContext, type AssistantMessage, type Capabilities, type Conversation, type Evidence } from '@/api/assistant'
import { fieldApi } from '@/api/field'
import { platformApi } from '@/api/platform'
import type { FieldItem, InspectionEventItem } from '@/types'
import AssistantAnswer from '@/components/assistant/AssistantAnswer.vue'
import AssistantEvidence from '@/components/assistant/AssistantEvidence.vue'

const route=useRoute(), conversations=ref<Conversation[]>([]), current=ref<Conversation|null>(null), messages=ref<AssistantMessage[]>([])
const capabilities=ref<Capabilities|null>(null), fields=ref<FieldItem[]>([]), inspections=ref<InspectionEventItem[]>([])
const files=ref<Attachment[]>([]), pending=ref<Attachment[]>([]), question=ref(''), search=ref(''), variety=ref('')
const context=reactive<AssistantContext>({field_id:null,inspection_id:null,crop:'烟草',growth_stage:'',location:''})
const loading=ref(true), sending=ref(false), uploading=ref(false), activeRun=ref<string|null>(null), error=ref(''), progress=ref('正在准备分析')
const historyOpen=ref(false), sourcesOpen=ref(false), backgroundOpen=ref(false), libraryOpen=ref(false), inputFocused=ref(false)
const webEnabled=ref(true), imageEnabled=ref(false), atBottom=ref(true), sourceList=ref<Evidence[]>([]), selectedSource=ref<Evidence|null>(null)
const scrollArea=ref<HTMLElement>(), input=ref<HTMLTextAreaElement>(), fileInput=ref<HTMLInputElement>()
const retryRequest=ref<{cid:string;data:Record<string,unknown>}|null>(null)
let streamController:AbortController|null=null, epoch=0
const busy=computed(()=>sending.value||!!activeRun.value)
const filteredHistory=computed(()=>conversations.value.filter(c=>c.title.toLowerCase().includes(search.value.toLowerCase())))
const availableInspections=computed(()=>inspections.value.filter(e=>!context.field_id||e.field_id===context.field_id))
const starters=[{title:'认识作物',description:'生长条件、症状与栽培知识',question:'烟草在旺长期需要关注哪些生长条件？',icon:ChatLineRound},{title:'看一次巡检',description:'梳理最近记录与复核重点',question:'总结我最近一次巡检，说明数据完整度和需要复核的地方。',icon:DataAnalysis},{title:'查天气',description:'未来变化与有效天气预警',question:'帮我查询天气，先确认需要查询的真实地区。',icon:Sunny},{title:'做个比较',description:'找到两次巡检的变化与依据',question:'帮我比较同一烟田最近两次巡检，先确认烟田和巡检记录。',icon:Document}]
function day(value:string|null|undefined){return value?new Date(value).toLocaleDateString('zh-CN'):'未开始'}
function clock(value:string){return new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function rememberScroll(){const el=scrollArea.value;if(el)atBottom.value=el.scrollHeight-el.scrollTop-el.clientHeight<100}
async function scrollBottom(force=false){await nextTick();if(scrollArea.value&&(force||atBottom.value)){scrollArea.value.scrollTop=scrollArea.value.scrollHeight;atBottom.value=true}}
function setContext(value?:AssistantContext){Object.assign(context,{field_id:null,inspection_id:null,crop:'烟草',growth_stage:'',location:''},value||{});variety.value=value?.variety||''}
function reset(){streamController?.abort();streamController=null;epoch++;activeRun.value=null;error.value='';retryRequest.value=null;sourceList.value=[];selectedSource.value=null;historyOpen.value=false}
function newChat(){if(sending.value)return;reset();current.value=null;messages.value=[];pending.value=[];question.value='';setContext();input.value?.focus()}
async function refreshHistory(){try{conversations.value=await assistantApi.list()}catch{error.value='历史记录同步暂时失败，刷新后可恢复；已提交的分析不会重复执行。'}}
async function openConversation(id:string){if(sending.value)return;reset();const ownEpoch=epoch;loading.value=true;try{const data=await assistantApi.detail(id);if(ownEpoch!==epoch)return;current.value=data;messages.value=data.messages||[];setContext(data.context);const last=[...messages.value].reverse().find(m=>m.evidence.length);if(last)showSources(last);await scrollBottom(true);if(data.active_run_id)void follow(data.active_run_id,id,ownEpoch)}catch(e){if(ownEpoch===epoch)error.value=asError(e)}finally{if(ownEpoch===epoch)loading.value=false}}
function normalizedContext(){return {...context,variety:variety.value,field_id:context.field_id||null,inspection_id:context.inspection_id||null}}
async function persistContext(){if(current.value&&!busy.value)await assistantApi.update(current.value.id,{context:normalizedContext()})}
async function fieldChanged(){context.inspection_id=null;variety.value='';context.location='';if(context.field_id){const saved=await assistantApi.fieldContext(context.field_id);Object.assign(context,{crop:saved.crop,growth_stage:saved.growth_stage,location:saved.location});variety.value=saved.variety||''}await persistContext()}
async function saveBackground(){try{if(context.field_id)await assistantApi.saveFieldContext(context.field_id,{crop:context.crop,variety:variety.value,growth_stage:context.growth_stage,location:context.location});await persistContext();backgroundOpen.value=false;ElMessage.success('分析背景已保存')}catch{/* existing notification */}}
function requestId(){if(crypto.randomUUID)return crypto.randomUUID();return Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('')}
async function send(text:string,regenerateId?:string){if(busy.value||uploading.value||text.trim().length<2)return;sending.value=true;error.value='';atBottom.value=true;try{if(!current.value)current.value=await assistantApi.create(normalizedContext());const cid=current.value.id;const data={question:text.trim(),client_request_id:requestId(),attachment_ids:pending.value.map(f=>f.id),web_enabled:webEnabled.value,image_enabled:imageEnabled.value,context:normalizedContext(),regenerate_message_id:regenerateId||null};retryRequest.value={cid,data};await submit(cid,data)}catch(e){error.value=asError(e)}finally{sending.value=false}}
async function submit(cid:string,data:Record<string,unknown>){const run=await assistantApi.run(cid,data);activeRun.value=run.id;question.value='';pending.value=[];const detail=await assistantApi.detail(cid);retryRequest.value=null;messages.value=detail.messages||[];current.value=detail;await scrollBottom(true);void refreshHistory();void follow(run.id,cid,epoch)}
async function retrySubmission(){if(!retryRequest.value||busy.value)return;sending.value=true;error.value='';try{await submit(retryRequest.value.cid,retryRequest.value.data)}catch(e){error.value=asError(e)}finally{sending.value=false}}
async function follow(rid:string,cid:string,ownEpoch:number){
  streamController?.abort();const controller=new AbortController();streamController=controller;activeRun.value=rid
  let finished=false
  const target=[...messages.value].reverse().find(m=>m.role==='assistant'&&(m.run_id===rid||['QUEUED','RUNNING'].includes(m.status)))
  if(target){target.content='';target.status='RUNNING';target.run_id=rid}
  try{await watchRun(rid,controller.signal,event=>{if(ownEpoch!==epoch||current.value?.id!==cid)return;const m=messages.value.find(v=>v.run_id===rid);if(event.kind==='status')progress.value=event.payload.text||'正在分析';if(event.kind==='delta'&&m){m.content+=event.payload.text||'';void scrollBottom()}if(event.kind==='evidence'&&m){m.evidence=event.payload.items||[];showSources(m)}if(event.kind==='error')error.value=event.payload.error||'回答未完成';if(['done','error'].includes(event.kind)){finished=true;if(m)m.status=event.payload.status||'COMPLETED'}})
    if(ownEpoch!==epoch)return;const result=await assistantApi.runDetail(rid);if(result.message){const index=messages.value.findIndex(m=>m.id===result.message!.id);if(index>=0)messages.value[index]={...result.message,run_id:rid};showSources(result.message)}finished=!['RUNNING','QUEUED'].includes(result.status);if(result.error)error.value=result.error
  }catch(e){if(!controller.signal.aborted&&ownEpoch===epoch)error.value=asError(e)+'；可以恢复连接，后台分析不会重复提交。'}finally{if(ownEpoch===epoch&&finished){activeRun.value=null;if(current.value)current.value.active_run_id=null;void refreshHistory()}}
}
async function resume(){if(activeRun.value&&current.value){error.value='';try{const detail=await assistantApi.detail(current.value.id);messages.value=detail.messages||[];current.value=detail;retryRequest.value=null;await follow(activeRun.value,detail.id,epoch)}catch(e){error.value=asError(e)}}}
async function stop(){try{if(activeRun.value)await assistantApi.cancel(activeRun.value)}catch(e){error.value=asError(e)}}
function showSources(m:AssistantMessage,open=false){sourceList.value=m.evidence;selectedSource.value=m.evidence.find(e=>e.id===selectedSource.value?.id)||m.evidence[0]||null;if(open)sourcesOpen.value=true}
function selectSource(m:AssistantMessage,id:string){sourceList.value=m.evidence;selectedSource.value=m.evidence.find(e=>e.id===id)||null;sourcesOpen.value=true}
async function copy(text:string){try{await navigator.clipboard.writeText(text);ElMessage.success('已复制')}catch{ElMessage.info('请选择文字手动复制')}}
async function regenerate(m:AssistantMessage){const index=messages.value.findIndex(v=>v.id===m.id);const original=[...messages.value.slice(0,index)].reverse().find(v=>v.role==='user');if(original){pending.value=files.value.filter(f=>original.attachment_ids.includes(f.id));if(pending.value.some(f=>f.kind==='IMAGE'))imageEnabled.value=true;await send(original.content,m.id)}}
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportAnswer(m:AssistantMessage,format:'md'|'csv'){if(!m.run_id){ElMessage.info('请重新打开对话后导出');return}download(await assistantApi.export(m.run_id,format),`Leafora分析记录.${format}`)}
async function downloadFile(id:string){const file=files.value.find(f=>f.id===id);if(!file){ElMessage.info('附件已移除');return}download(await assistantApi.file(id),file.title)}
function attach(file:Attachment){if(pending.value.some(f=>f.id===file.id))return;if(pending.value.filter(f=>f.kind===file.kind).length>=(file.kind==='IMAGE'?3:5)){ElMessage.warning(file.kind==='IMAGE'?'每次最多3张图片':'每次最多5份文档');return}pending.value.push(file);if(file.kind==='IMAGE')imageEnabled.value=true;libraryOpen.value=false}
async function uploadFiles(event:Event){const target=event.target as HTMLInputElement,selected=Array.from(target.files||[]);target.value='';uploading.value=true;try{for(const file of selected){const uploaded=await assistantApi.upload(file);if(!files.value.some(f=>f.id===uploaded.id))files.value.unshift(uploaded);attach(uploaded)}}catch{/* existing notification */}finally{uploading.value=false}}
async function removeFile(file:Attachment){try{await ElMessageBox.confirm(`移除“${file.title}”？之后助手不再检索该资料。`,'移除资料',{type:'warning'});await assistantApi.removeAttachment(file.id);files.value=files.value.filter(f=>f.id!==file.id);pending.value=pending.value.filter(f=>f.id!==file.id)}catch{/* cancelled or notified */}}
async function rename(c:Conversation){try{const result=await ElMessageBox.prompt('输入新的对话标题','重命名',{inputValue:c.title,inputValidator:value=>!!value?.trim()&&value.length<=100});await assistantApi.update(c.id,{title:result.value.trim()});if(current.value?.id===c.id)current.value.title=result.value.trim();await refreshHistory()}catch{/* cancelled or notified */}}
async function removeConversation(c:Conversation){try{await ElMessageBox.confirm('删除后将移除该对话和分析记录。','删除对话',{type:'warning'});await assistantApi.delete(c.id);if(current.value?.id===c.id)newChat();await refreshHistory()}catch{/* cancelled or notified */}}
function asError(e:unknown){return e instanceof Error?e.message:'服务暂时不可用，请稍后重试'}
function handleKey(event:KeyboardEvent){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();void send(question.value)}}
